#include "passport.hpp"
#include <iostream>
#include <functional>
int main(){int groups=0,asserts=0;auto check=[&](bool b){++asserts;if(!b)throw std::runtime_error("assertion failed");};auto fail=[&](const std::function<void()>&f){try{f();return false;}catch(const std::runtime_error&){return true;}};auto test=[&](const char*n,const std::function<void()>&f){f();++groups;std::cout<<"PASS "<<n<<'\n';};try{
test("independent binary16 golden words",[&]{for(auto pair:std::vector<std::pair<float,unsigned>>{{0,0},{-0.0f,0x8000},{1,0x3c00},{-2,0xc000},{65504,0x7bff},{std::ldexp(1.0f,-14),0x400},{std::ldexp(1.0f,-24),1}})check(precision::half_bits(pair.first)==pair.second);});
test("nearest ties even normal subnormal overflow",[&]{check(precision::half(1+std::ldexp(1.0f,-11))==1);check(precision::half(1+3*std::ldexp(1.0f,-11))==1+std::ldexp(1.0f,-9));check(precision::half_bits(std::ldexp(1.0f,-25))==0);check(precision::half_bits(3*std::ldexp(1.0f,-25))==2);check(std::isinf(precision::half(65520)));});
test("all finite half codes roundtrip",[&]{for(unsigned h=0;h<65536;++h)if((h&0x7c00)!=0x7c00)check(precision::half_bits(precision::half_value(static_cast<std::uint16_t>(h)))==h);});
test("NaN infinity signed zero classification",[&]{auto inf=std::numeric_limits<double>::infinity(),nan=std::numeric_limits<double>::quiet_NaN();check(precision::compare(nan,nan,0,0).match);check(!precision::compare(nan,1,0,0).match);check(precision::compare(inf,inf,0,0).match);check(!precision::compare(inf,-inf,0,0).match);check(precision::compare(0,-0.0,0,0).match);check(std::isnan(precision::half(std::numeric_limits<float>::quiet_NaN())));});
test("cancellation mismatch and float32 control",[&]{std::vector<float>x{2048,1,-2048};check(precision::reference_sum(x)==1);check(precision::sum(x,true)==0);check(precision::sum(x,false)==1);check(precision::mismatch(x,.25,0));});
test("stable exact range negative controls",[&]{for(int n=1;n<64;++n){std::vector<float>x(n,.5);check(!precision::mismatch(x,0,0));check(precision::sum(x,false)==precision::reference_sum(x));}});
test("reducer preserves mismatch one deletion minimal",[&]{auto x=precision::minimize({0,2048,1,-2048,0},.25,0);check(x.size()==2);check(precision::mismatch(x,.25,0));for(std::size_t i=0;i<x.size();++i){auto y=precision::without(x,i);check(!precision::mismatch(y,.25,0));}});
test("overflow mismatch unlike finite error",[&]{auto c=precision::compare(precision::reference_sum({65504,65504}),precision::sum({65504,65504},true),.25,0);check(!c.match&&c.classification=="infinity_classification");});
test("abs relative tolerances and identical runs",[&]{check(precision::compare(100,101,0,.01).match);check(!precision::compare(100,101,0,.009).match);check(precision::compare(0,.25,.25,0).match);check(precision::compare(precision::sum({.1f,.2f},false),precision::sum({.1f,.2f},false),0,0).match);});
test("invalid bounds tolerance and nonfailing reducer",[&]{check(fail([&]{precision::reference_sum({});}));check(fail([&]{precision::reference_sum(std::vector<float>(4097));}));check(fail([&]{precision::compare(0,0,-1,0);}));check(fail([&]{precision::compare(0,0,0,std::numeric_limits<double>::infinity());}));check(fail([&]{precision::minimize({1,2},0,0);}));});
test("passport exact input reproduction",[&]{auto text=precision::passport({0,2048,1,-2048,0},.25,0);check(text.find("\"metal_tested\":false")!=std::string::npos);check(text.find("45000000")!=std::string::npos);check(text.find("3f800000")!=std::string::npos);check(text==precision::passport({0,2048,1,-2048,0},.25,0));});
std::cout<<"SUMMARY groups="<<groups<<" assertions="<<asserts<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
